      const fb = faces[b];
      if (!fa.visible || !fb.visible || fa.i === fb.i) continue;
      const k = 3 - fa.i - fb.i;
      const s0 = [0, 0, 0];
      s0[fa.i] = fa.sign;
      s0[fb.i] = fb.sign;
